#!/usr/bin/env bash
# Attach trimmed.log to the ticket and notify the channel.
echo "upload $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
cd /work
python3 << 'EOF'
items = [
"# deploy report 2026-08-14 build 118 (api-server)",
"ERROR 09:14:33 container api-2 failed health check /readyz after 30s",
"ERROR 09:15:02 rollback of api-2 incomplete: volume detach timed out",
"ERROR 09:16:40 build 118 marked bad; pipeline halted at stage staging",
]
def overlap(a,b):
    maxk = min(len(a), len(b))
    best=0
    for k in range(1, maxk+1):
        if a[-k:] == b[:k]:
            best = k
    return best
for i,a in enumerate(items):
    for j,b in enumerate(items):
        if i!=j:
            ov = overlap(a,b)
            if ov>0:
                print(i,j,ov)
print("done")
EOF
